-- Simulacros calcados a los exámenes reales (informe de 05/11/2026, /mnt/project-files/aprobia/examenes-reales/).
-- * Simulacros normales: config.quotas (migración 20261105000100_mock_quotas) saca de cada tema el número de
--   preguntas de los exámenes oficiales. Los simulacros por partes de la AGE llevan una entrada por tema.
-- * Notas de corte reales: Policía Nacional 7 (corte 2026: 7,05); Administrativo parte 1, 23 sobre 50.
-- * Nuevos: segunda parte de Administrativo (tipo supuesto), ofimática de Tramitación (tercer ejercicio) y
--   simulacro completo de Policía Nacional (temas 1-45). El pack de Policía Nacional pasa a ser el temario
--   completo (ya no solo Ciencias Jurídicas).
-- Idempotente. Requiere la migración de cupos, 41- y 42- (temas nuevos publicados).
begin;

insert into public.products (slug, type, status, title, title_ca, description, description_ca,
                             exam_body_id, is_free, included_in_premium, config)
select v.slug, 'mock_exam', 'draft', v.title, v.title_ca, '', '', b.id, false, true, '{}'::jsonb
  from (values
    ('age-adm-simulacro-parte-2-2026', 'administrativo-estado', 'Administrativo del Estado · Simulacro de la segunda parte (tipo supuesto)', 'Administratiu de l''Estat · Simulacre de la segona part (tipus supòsit)'),
    ('jus-tramitacion-simulacro-ofimatica-2026', 'tramitacion-procesal', 'Tramitación Procesal · Simulacro de ofimática (tercer ejercicio)', 'Tramitació Processal · Simulacre d''ofimàtica (tercer exercici)'),
    ('pn-simulacro-completo-2026', 'policia-nacional-basica', 'Policía Nacional · Simulacro completo (100 preguntas)', 'Policia Nacional · Simulacre complet (100 preguntes)')
  ) as v(slug, exam, title, title_ca)
  join public.exam_bodies b on b.slug = v.exam
on conflict (slug) do nothing;

