insert into public.product_items (product_id, position, child_product_id)
select pk.id, coalesce((select max(position) from public.product_items x where x.product_id = pk.id), 0) + 1, c.id
  from (values
    ('age-adm-pack-completo-2026', 'age-adm-simulacro-parte-2-2026'),
    ('jus-tramitacion-pack-completo-2026', 'jus-tramitacion-simulacro-ofimatica-2026'),
    ('pn-pack-completo-2026', 'pn-simulacro-completo-2026')
  ) as v(pack, child)
  join public.products pk on pk.slug = v.pack
  join public.products c on c.slug = v.child
 where not exists (select 1 from public.product_items i where i.product_id = pk.id and i.child_product_id = c.id);

-- Policía Nacional: el pack de test ya cubre los temas 1-45 (prefijo pn-)
update public.products
   set title = 'Policía Nacional · Temario completo (test de 3 opciones)',
       title_ca = 'Policia Nacional · Temari complet (test de 3 opcions)',
       description = 'Preguntas tipo test de 3 alternativas de los temas 1 a 45 del programa oficial (BOE 10/07/2026): Ciencias Jurídicas, Sociales y Técnico-Científicas, con la cita literal de la fuente oficial (BOE, RAE, IGN, INCIBE, CNI, DGT...). Los temas 28 y 29 aún no tienen preguntas porque no hay fuente oficial que los desarrolle.',
       description_ca = 'Preguntes tipus test de 3 alternatives dels temes 1 a 45 del programa oficial, amb la cita literal de la font oficial. Els temes 28 i 29 encara no en tenen.'
 where slug = 'pn-ciencias-juridicas-2026';

update public.products
   set description = 'Temario completo (temas 1 a 45, salvo 28 y 29) en preguntas de 3 opciones con su fuente, simulacro completo de 100 preguntas y simulacro de Ciencias Jurídicas con el corte real (7), repaso de errores y plan de estudio semanal.'
 where slug = 'pn-pack-completo-2026';

-- Publicar los simulacros nuevos si sus cupos tienen preguntas publicadas suficientes
update public.products p set status = 'published'
 where p.slug in ('age-adm-simulacro-parte-2-2026', 'jus-tramitacion-simulacro-ofimatica-2026', 'pn-simulacro-completo-2026')
   and p.status = 'draft'
   and ((p.config->>'kind' = 'sections' and public.mock_sections_ready(p.id))
        or (coalesce(p.config->>'kind', '') <> 'sections' and public.mock_quotas_ready(p.id)));

commit;
